// Called only inside a new, atomic reward transaction; never during rendering or loading.
function creditSlotCoins(prize){
 const w=lifeData.slot.wallet,before=w.balance;
 w.balance=Math.min(999999,before+arcadeInt(prize,0,999999));
 const credited=w.balance-before;w.won=Math.min(1e12,w.won+credited);return credited;
}
function displayedSlotCoins(){return slotVisible()&&slotVisualCoins!==null?slotVisualCoins:lifeData.slot.wallet.balance;}

