  const chip=uNode('span','bn-slot-reward '+kind),count=uNode('strong',kind==='lives'?'bn-world-win-count':'bn-world-coin-count',(winning?'+':'')+value);count.id=id;
  chip.append(uNode('i','',icon),count,uNode('small','',label));row.append(chip);
 }
