  if(celebrating){const collect=uButton('CONTINUA',finishSlotCelebration,'bn-world-skip');collect.id='slotCollectButton';outcome.append(collect);}
 }else outcome.append(uNode('span','',last?'ULTIMO GIRO':'VINCI MONETE E VITE'));

